mapper.select:
SELECT * FROM api_key
 WHERE primary_principal = #{primaryPrincipal, typeHandler=EncryptedStringTypeHandler}
   AND domain = #{domain};

mapper.insert:
INSERT INTO api_key (primary_principal, domain, token, principals, created)
    VALUES (#{primaryPrincipal, typeHandler=EncryptedStringTypeHandler},
            #{domain}, #{token}, #{principals}, #{created});

mapper.delete:
DELETE FROM api_key
    WHERE primary_principal = #{primaryPrincipal, typeHandler=EncryptedStringTypeHandler}
    AND domain = #{domain};

DELETE FROM api_key
    WHERE domain = #{domain}
      AND token = #{token};

mapper.select:
SELECT *
  FROM api_key
WHERE domain = #{domain}
ORDER BY created;

SELECT *
  FROM api_key
WHERE domain = #{domain}
  AND created > #{created}
ORDER BY created;

SELECT count(*)
  FROM api_key
 WHERE domain = #{domain};

mapper.delete:
DELETE FROM api_key
WHERE domain = #{domain}
  AND created < #{expiration};

mapper.update:
INSERT INTO api_key (primary_principal
                    , domain
                    , token
                    , principals
                    , created)
VALUES (#{primaryPrincipal, typeHandler=EncryptedStringTypeHandler}
        , #{domain}
        , #{token}
        , #{principals}
        , #{created})
ON CONFLICT (domain, token)
DO UPDATE SET
  token = #{token}
  , primary_principal = #{primaryPrincipal, typeHandler=EncryptedStringTypeHandler}
  , principals = #{principals}
  , created = #{created};

 MERGE INTO api_key (primary_principal, domain, token,
                     principals , created)
   KEY (domain, token)
VALUES (#{primaryPrincipal, typeHandler=EncryptedStringTypeHandler}
        , #{domain}
        , #{token}
        , #{principals}
        , #{created});

mapper.select:
SELECT *
FROM api_key
WHERE domain = #{domain}
ORDER BY created
LIMIT #{limit}
OFFSET #{skip};

  SELECT *
    FROM api_key
   WHERE created > #{created}
ORDER BY created
   LIMIT #{limit};
